MOD = 998244353

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    robots = []
    for i in range(N):
        X = int(data[2 * i + 1])
        D = int(data[2 * i + 2])
        robots.append((X, D))

    @lru_cache(None)
    def dp(mask):
        if mask == 0:
            return 1
        count = 0
        for i in range(N):
            if mask & (1 << i):
                new_mask = mask
                for j in range(N):
                    if i != j and mask & (1 << j) and robots[j][0] >= robots[i][0] and robots[j][0] < robots[i][0] + robots[i][1]:
                        new_mask &= ~(1 << j)
                count += dp(new_mask)
                count %= MOD
        return count

    result = dp((1 << N) - 1)
    print(result)

